(()=>{'use strict';const images={'/custom-plastic-cups/':'/img/v88-20261023/bsb-001-b6ae1a7de6.webp','/custom-silicone-cups/':'/img/v88-20261023/bpjj-002-00d6f883f9.webp','/led-light-up-cups/':'/img/v88-20261023/fgb-006-155c041e6e.webp','/custom-ice-buckets/':'/img/v88-20261023/bt-003-2b52b4df21.webp','/bar-accessories/':'/img/v88-20261023/bd-001-98b73d1813.webp'};let queued=false;function decorate(){queued=false;const main=document.querySelector('main');if(!main)return;const home=location.pathname==='/'||location.pathname==='/zh/';document.body.dataset.ecPage=home?'home':'interior';if(home){const sections=[...main.children].filter(x=>x.tagName==='SECTION');sections[0]?.classList.add('ec-home-hero');const cats=sections.find(s=>s.querySelector('a[href="/custom-plastic-cups/"]')&&s.querySelector('h2'));if(cats){cats.classList.add('ec-home-categories');for(const a of cats.querySelectorAll('a')){const img=a.querySelector('img');if(img&&images[a.getAttribute('href')]&&img.getAttribute('src')!==images[a.getAttribute('href')]){img.removeAttribute('srcset');img.src=images[a.getAttribute('href')];}}}}}const obs=new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(decorate)}});function start(){decorate();obs.observe(document.getElementById('root')||document.body,{subtree:true,childList:true});const top=document.createElement('button');top.className='ec-back-top';top.type='button';top.setAttribute('aria-label',document.documentElement.lang.startsWith('zh')?'返回顶部':'Back to top');top.textContent='↑';top.addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));document.body.append(top);const update=()=>top.classList.toggle('is-visible',scrollY>700);addEventListener('scroll',update,{passive:true});update();}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start,{once:true}):start();})();
